// Trebuchet MS TrueType font embedded for jsPDF (Node.js Server)
export const TREBUCHET_REGULAR_B64 = '';
export const TREBUCHET_BOLD_B64 = '';

export function registerTrebuchetFont(doc) {
  if (!doc) return;
  try {
    if (!doc.__trebuchetRegistered) {
      doc.addFileToVFS('TrebuchetMS-Regular.ttf', TREBUCHET_REGULAR_B64);
      doc.addFont('TrebuchetMS-Regular.ttf', 'TrebuchetMS', 'normal');
      doc.addFileToVFS('TrebuchetMS-Bold.ttf', TREBUCHET_BOLD_B64);
      doc.addFont('TrebuchetMS-Bold.ttf', 'TrebuchetMS', 'bold');
      doc.__trebuchetRegistered = true;
    }
    doc.setFont('TrebuchetMS', 'normal');
  } catch (e) {
    try { doc.setFont('Helvetica', 'normal'); } catch {}
  }
}

export function setTrebuchetFont(doc, style = 'normal') {
  if (!doc) return;
  try {
    if (!doc.__trebuchetRegistered) {
      registerTrebuchetFont(doc);
    }
    doc.setFont('TrebuchetMS', style === 'bold' ? 'bold' : 'normal');
  } catch (e) {
    try { doc.setFont('Helvetica', style === 'bold' ? 'bold' : 'normal'); } catch {}
  }
}
